// Build the Gemini generateContent request for a post draft (or a revision).
const p = $input.first().json;
const feedback = String($('When Called').first().json.feedback || '').trim();

const list = (arr) => (Array.isArray(arr) ? arr.filter(Boolean) : []);
const brand = [
  `Business name: ${p.client_name}`,
  p.business_description && `About the business: ${p.business_description}`,
  p.audience && `Target audience: ${p.audience}`,
  p.voice && `Brand voice: ${p.voice}`,
  `Language: ${p.language || 'English'}`,
  p.emoji_policy && `Emoji use: ${p.emoji_policy}`,
  p.default_cta && `Default call to action: ${p.default_cta}`,
  list(p.brand_hashtags).length && `Brand hashtags (always relevant): ${list(p.brand_hashtags).join(' ')}`,
  list(p.banned_words).length && `Never use these words: ${list(p.banned_words).join(', ')}`,
  p.sample_posts && `Examples of past posts in the brand's style:\n${p.sample_posts}`,
].filter(Boolean).join('\n');

const system = `You write social media posts for a small business. The business owner reviews every draft before anything is published.

Facebook caption: conversational and complete, usually 40-120 words unless the brief asks for something else. Links and phone numbers are fine when the brief provides them. Use at most 3 hashtags inline.

Instagram caption: the first line must hook the reader because the feed cuts it off after about 125 characters. Use short paragraphs and end with a clear call to action. Do not include URLs because they are not clickable on Instagram; say "link in bio" if a link matters. Do not put hashtags in the caption text.

Hashtags: return 5-15 relevant Instagram hashtags in the hashtags field, mixing broad, niche and local tags. Each starts with # and has no spaces.

Only state prices, dates, offers, addresses and contact details that appear in the brief or brand profile. If something the post clearly needs is missing, write around it and mention it in notes_for_client. Keep notes_for_client to one or two short sentences, or an empty string when nothing is worth flagging.

Write in the brand's language and voice.`;

let text = `<brand_profile>\n${brand}\n</brand_profile>\n\n<brief>\n${p.brief || '(No written brief. Base the post on the attached photo.)'}\n</brief>`;
if (p.source_media_url) text += '\n\nThe attached photo will be published together with both captions.';
if (feedback) {
  text += `\n\n<previous_draft>\nFacebook:\n${p.prev_fb || ''}\n\nInstagram:\n${p.prev_ig || ''}\n</previous_draft>`;
  text += `\n\n<client_feedback>\n${feedback}\n</client_feedback>\n\nRevise the draft to address the client's feedback. Keep everything they did not ask to change.`;
}

const parts = [{ text }];

return [{
  json: {
    post_id: p.post_id,
    chat_id: p.chat_id,
    platforms: p.platforms || [],
    source_media_url: p.source_media_url || null,
    brand_hashtags: list(p.brand_hashtags),
    banned_words: list(p.banned_words),
    feedback,
    request: {
      systemInstruction: {
        parts: [{ text: system }]
      },
      contents: [
        {
          role: 'user',
          parts
        }
      ],
      generationConfig: {
        responseMimeType: 'application/json',
        responseSchema: {
          type: 'OBJECT',
          properties: {
            facebook_caption: { type: 'STRING' },
            instagram_caption: { type: 'STRING' },
            hashtags: { type: 'ARRAY', items: { type: 'STRING' } },
            notes_for_client: { type: 'STRING' }
          },
          required: ['facebook_caption', 'instagram_caption', 'hashtags', 'notes_for_client']
        }
      }
    },
  },
}];

// Parse Gemini/AI structured output and enforce platform limits.
const { request, ...base } = $('Build AI Request').first().json;
const res = $input.first().json;
const fail = (reason) => [{ json: { ...base, ok: false, reason } }];

// Gemini finish reasons
const candidate = res.candidates?.[0];
if (candidate?.finishReason === 'SAFETY') return fail('the AI declined this brief due to safety filters. Try rephrasing it');
if (candidate?.finishReason === 'MAX_TOKENS' || res.stop_reason === 'max_tokens') return fail('the draft was cut off. Try a shorter brief');
if (res.stop_reason === 'refusal') return fail('the AI declined this brief. Try rephrasing it');

// Extract text from Gemini candidates or standard response format
const textOutput =
  candidate?.content?.parts?.[0]?.text ||
  (res.content || []).find((b) => b.type === 'text')?.text ||
  res.text ||
  '';

if (!textOutput) return fail('the AI returned an empty response');

let d;
try {
  d = JSON.parse(textOutput);
} catch (e) {
  return fail('the AI returned malformed output');
}

const IG_CAPTION_MAX = 2200;
const IG_HASHTAGS_MAX = 30;
const FB_CAPTION_MAX = 5000;

const clean = (s) => String(s || '').replace(/\r\n/g, '\n').replace(/[ \t]+\n/g, '\n').trim();

const fb = clean(d.facebook_caption).slice(0, FB_CAPTION_MAX);
const igBody = clean(String(d.instagram_caption || '').replace(/https?:\/\/\S+/g, ''));

const tags = [...new Set(
  [...base.brand_hashtags, ...(d.hashtags || [])]
    .map((t) => '#' + String(t).replace(/^#+/, '').replace(/[^\p{L}\p{N}_]/gu, ''))
    .filter((t) => t.length > 1),
)].slice(0, IG_HASHTAGS_MAX);

// Drop hashtags from the end until the caption fits; truncate the body only as a last resort.
let ig = igBody;
for (let n = tags.length; n >= 0; n--) {
  ig = n ? `${igBody}\n\n${tags.slice(0, n).join(' ')}` : igBody;
  if (ig.length <= IG_CAPTION_MAX) break;
}
if (ig.length > IG_CAPTION_MAX) ig = ig.slice(0, IG_CAPTION_MAX - 1) + '…';

const warnings = [];
const lower = `${fb}\n${ig}`.toLowerCase();
for (const word of base.banned_words) {
  if (word && lower.includes(word.toLowerCase())) warnings.push(`Contains a banned word: "${word}"`);
}
if (!fb) warnings.push('Facebook caption is empty');
if (!igBody) warnings.push('Instagram caption is empty');

return [{
  json: {
    ...base,
    ok: true,
    fb_caption: fb,
    ig_caption: ig,
    notes: clean(d.notes_for_client),
    warnings,
    model: res.modelVersion || res.model || 'gemini-2.5-flash',
  },
}];

// Approval message + buttons. Plain text (no parse_mode) so captions never break formatting.
const d = $('Validate Draft').first().json;
const version = $input.first().json.version;
const platforms = d.platforms || [];
const id = d.post_id;

const label = { facebook: 'Facebook', instagram: 'Instagram' };
const parts = [
  `📝 DRAFT v${version} · ${platforms.length ? platforms.map((p) => label[p] || p).join(' + ') : '⚠️ no platform available'}`,
];
if (platforms.includes('facebook')) parts.push(`📘 FACEBOOK\n${d.fb_caption.slice(0, 1400)}`);
if (platforms.includes('instagram')) parts.push(`📸 INSTAGRAM\n${d.ig_caption}`);
if (!d.source_media_url) parts.push('ℹ️ No photo attached, so Instagram is skipped. Send a photo with your brief to include Instagram.');
if (d.notes) parts.push(`💡 ${d.notes}`);
for (const w of d.warnings) parts.push(`⚠️ ${w}`);
parts.push('Nothing is posted until you tap 🚀 or schedule it.');

let text = parts.join('\n\n');
if (text.length > 4096) text = text.slice(0, 4090) + '…';

const inline_keyboard = [];
if (platforms.length) {
  inline_keyboard.push([
    { text: '🚀 Publish now', callback_data: `p:pub:${id}` },
    { text: '🕒 Schedule', callback_data: `p:sch:${id}` },
  ]);
}
inline_keyboard.push([
  { text: '✏️ Edit', callback_data: `p:edt:${id}` },
  { text: '🔁 Regenerate', callback_data: `p:rgn:${id}` },
  { text: '❌ Discard', callback_data: `p:rej:${id}` },
]);

return [{
  json: {
    chat_id: d.chat_id,
    text,
    reply_markup: { inline_keyboard },
    photo_url: d.source_media_url,
    has_photo: !!d.source_media_url,
  },
}];

// HTTP error from the Gemini/AI API (after node-level retries).
const { request, ...base } = $('Build AI Request').first().json;
const err = $input.first().json.error ?? {};
const message = typeof err === 'string' ? err : err.message || 'unknown error';
return [{ json: { ...base, ok: false, reason: `the AI service failed (${String(message).slice(0, 200)})` } }];

